import {calculate} from './engine.mjs';
import {predictProfile} from './model.mjs';
const $=s=>document.querySelector(s), money=v=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(v), number=v=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1}).format(v);
let last=null,lastInput=null,rowId=0;const names={prior:'Tarif initial',bayes:'Prime bayésienne',credibility:'Crédibilité structurelle'};
let model,report,acceptance;
try {
 [model,report,acceptance]=await Promise.all(['model.json','calibration.json','acceptance.json'].map(async file=>{const response=await fetch(file,{cache:'no-cache'});if(!response.ok)throw new Error('Chargement du modèle indisponible.');return response.json();}));
}catch(error){$('#errors').hidden=false;$('#errors').textContent='Le dossier du modèle ne peut pas être chargé. Aucun calcul n’est disponible.';document.querySelectorAll('button').forEach(button=>button.disabled=true);throw error;}
$('#Region').replaceChildren(...Object.keys(model.frequency.coefficients.Region).map(region=>{const option=document.createElement('option');option.value=region;option.textContent=region;option.selected=region==='Centre';option.defaultSelected=region==='Centre';return option;}));
function currentProfile(){const p={};for(const name of ['DrivAge','VehAge','VehPower']){const value=$('#'+name).value;if(!value.trim())throw new Error('Complétez les caractéristiques du profil.');p[name]=Number(value);}for(const name of ['VehGas','Area','Region'])p[name]=$('#'+name).value;return p;}
function currentPrediction(){const value=$('#costIndex').value;if(!value.trim())throw new Error('Renseignez le facteur d’évolution des coûts.');const p=predictProfile(currentProfile(),model,Number(value));for(const key of ['frequency','severity','beta','k'])$('#'+key).value=p[key].toFixed(key==='frequency'?6:2);return p;}
const testReport=report.metrics.find(row=>row.sample==='test');
$('#model-version').textContent=`${model.version} · source CASdatasets ${model.data_commit.slice(0,12)} · données historiques, environ 2011–2013.`;
$('#validation-kpis').innerHTML=[['Contrats de calibration',model.trained_policies.toLocaleString('fr-FR'),'Apprentissage uniquement'],['Contrats de test',model.test_policies.toLocaleString('fr-FR'),'Jamais utilisés pour le réglage'],['Charge observée / prédite',number(testReport.observed_predicted_cost*100)+' %','Équilibre recherché : 100 %']].map(([label,value,note])=>`<article class="comparison-item"><h3>${label}</h3><strong>${value}</strong><p>${note}</p></article>`).join('');
$('#validation-metrics').innerHTML=report.metrics.map(row=>`<tr><td>${{train:'Apprentissage',validation:'Validation',test:'Test'}[row.sample]}</td><td>${row.policies.toLocaleString('fr-FR')}</td><td>${row.observed_predicted_count.toFixed(3)}</td><td>${row.observed_predicted_cost.toFixed(3)}</td><td>${row.pure_tweedie_deviance_p15.toFixed(3)}</td></tr>`).join('');
$('#audit-details').textContent=`${report.data_audit.raw_policies.toLocaleString('fr-FR')} contrats uniques, ${report.data_audit.raw_claims.toLocaleString('fr-FR')} sinistres. Aucun nombre de sinistres incohérent ni montant orphelin. Exposition conservée sans duplication. Gros sinistres inclus dans le bilan.`;
$('#credibility-details').textContent=`r = ${model.frailty_shape_r.toFixed(4)}, estimé sur l’apprentissage. β = r / fréquence. Le facteur de second moment des coûts vaut ${model.severity_second_moment_factor.toFixed(2)}. K est structurel ; aucune validation de renouvellement longitudinal n’est revendiquée.`;
$('#validation-details').textContent=`Sur le test : charge observée ${money(testReport.observed_cost)}, prédite ${money(testReport.predicted_cost)}. L’intervalle d’échantillonnage du ratio O/P est [${report.test_aggregate_cost_op_bootstrap95.map(v=>number(100*v)+' %').join(' ; ')}]. La source historique ne valide pas un tarif actuel.`;
for(const check of acceptance.checks){const li=document.createElement('li');li.textContent=`${check.pass?'✓':'À revoir ·'} ${check.name}`;$('#acceptance-checks').append(li);}
function addRow(months=12,claims=0,amount=0){const id=++rowId,tr=document.createElement('tr');tr.innerHTML=`<td>Année <span class="row-number"></span></td><td><input aria-label="Mois assurés, période ${id}" class="months" type="number" min="0" max="12" step="0.1" value="${months}" required></td><td><input aria-label="Nombre de sinistres, période ${id}" class="claims" type="number" min="0" step="1" value="${claims}" required></td><td><input aria-label="Charge totale en euros, période ${id}" class="amount" type="number" min="0" step="1" value="${amount}" required></td><td><button type="button" class="delete" aria-label="Supprimer la période ${id}">×</button></td>`;tr.querySelector('.delete').onclick=()=>{tr.remove();renumber();dirty();};$('#history-body').append(tr);renumber();}
function renumber(){document.querySelectorAll('.row-number').forEach((el,i)=>el.textContent=i+1);$('#add-year').disabled=$('#history-body').children.length>=20;}
function read(){const prediction=currentPrediction();const num=id=>{const el=$('#'+id);if(!el.value.trim())throw new Error('Complétez tous les paramètres numériques.');return Number(el.value);};const history=[...document.querySelectorAll('#history-body tr')].map(tr=>{const value=selector=>{if(!tr.querySelector(selector).value.trim())throw new Error('Complétez les valeurs de chaque période.');return Number(tr.querySelector(selector).value);};return {exposure:value('.months')/12,claims:value('.claims'),amount:value('.amount')};});return {frequency:prediction.frequency,severity:prediction.severity,beta:prediction.beta,k:prediction.k,history,method:$('input[name="method"]:checked').value,coverage:num('coverage'),fixedFee:num('fixedFee'),expenseRate:num('expenseRate')/100,marginRate:num('marginRate')/100,profile:currentProfile(),costIndex:prediction.costIndex,modelVersion:model.version};}
function dirty(){ $('#result-status').textContent='À recalculer';$('#export').disabled=true;$('#print').disabled=true;try{const v=read();$('#prior-tile').textContent=money(v.frequency*v.severity);$('#history-summary').textContent=`${number(v.history.reduce((s,r)=>s+r.exposure,0))} années · ${v.history.reduce((s,r)=>s+r.claims,0)} sinistre(s)`;}catch{}}
function render(r,input){$('#result-status').textContent='À jour';$('#export').disabled=false;$('#print').disabled=false;$('#premium').replaceChildren(document.createTextNode(new Intl.NumberFormat('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(r.premium)+' '));const euro=document.createElement('span');euro.textContent='€';$('#premium').append(euro);$('#payment').textContent=`soit ${money(r.monthly)} / mois sur ${number(input.coverage*12)} mois, sans frais de fractionnement`;
$('#change').textContent=`${r.change<0?'↘':r.change>0?'↗':'→'} ${r.change>0?'+':''}${number(r.change)} % sur la prime pure`;
$('#annual-pure').textContent=money(r.annualPure);$('#period-pure').textContent=money(r.periodPure);$('#loadings').textContent=money(r.expenses+r.margin);$('#duration').textContent=number(input.coverage*12)+' mois';
const z=input.method==='bayes'?r.zBayes:input.method==='credibility'?r.zCredibility:0;$('#weight').textContent=number(z*100)+' %';$('#weight-bar').style.width=z*100+'%';
$('#explanation-title').textContent=input.method==='prior'?'Le profil donne la référence.':!r.t?'Un nouveau départ.':r.change<0?'L’expérience joue en votre faveur.':r.change>0?'L’expérience ajuste le risque.':'Un historique cohérent avec le tarif.';
$('#explanation').textContent=!r.t?'Sans historique, la prime ajustée rejoint le tarif initial. La durée assurée permettra de personnaliser progressivement cette estimation.':input.method==='prior'?'Le calcul utilise uniquement le tarif de référence. Votre historique n’intervient pas dans cette méthode.':input.method==='bayes'?`${r.n} sinistre(s) sur ${number(r.t)} années assurées : cet historique pèse ${number(z*100)} % dans la fréquence ajustée. Le coût moyen par sinistre reste celui du tarif initial.`:`Une charge de ${money(r.s)} sur ${number(r.t)} années, soit ${money(r.s/r.t)} par an. Elle est combinée à votre tarif initial de ${money(r.prior)}.`;
$('#method-note').textContent=input.method==='bayes'?`Fréquence ajustée : ${number(r.posteriorFrequency*100)} sinistres pour 100 années assurées. Modèle Poisson-Gamma.`:input.method==='credibility'?`Crédibilité sur les coûts · K = ${number(input.k)} années. K est dérivé du modèle collectif ; les charges doivent être matures et dans la même base économique.`:'Prime pure = fréquence annuelle attendue × coût moyen.';
const descriptions={prior:'Le profil donne la référence, avant expérience individuelle.',bayes:'Le nombre de sinistres ajuste la fréquence. Le coût moyen est conservé.',credibility:'La charge passée annualisée ajuste directement la prime pure.'};
$('#comparison-cards').innerHTML=['prior','bayes','credibility'].map(key=>`<article class="comparison-item"><h3>${names[key]}</h3><strong>${money(r[key])}</strong><p>${descriptions[key]}</p></article>`).join('');const max=Math.max(r.prior,r.bayes,r.credibility,1);$('#comparison-chart').innerHTML=['prior','bayes','credibility'].map(key=>`<div class="chart-line"><span>${names[key]}</span><div class="chart-track"><div class="chart-bar" style="width:${r[key]/max*100}%"></div></div><strong>${money(r[key])}</strong></div>`).join('');}
function submit(event){event?.preventDefault();try{const input=read(),r=calculate(input);if(!Number.isFinite(r.premium)||!Number.isFinite(r.annualPure))throw new Error('Les valeurs saisies dépassent la plage de calcul.');last=r;lastInput=input;$('#errors').hidden=true;render(r,input);}catch(e){$('#errors').hidden=false;$('#errors').textContent=e.message;$('#result-status').textContent='Saisie à corriger';$('#export').disabled=true;$('#print').disabled=true;$('#errors').scrollIntoView({behavior:'smooth',block:'center'});}}
$('#pricing-form').addEventListener('submit',submit);$('#pricing-form').addEventListener('input',dirty);$('#pricing-form').addEventListener('change',dirty);
$('#add-year').onclick=()=>{if($('#history-body').children.length<20){addRow();dirty();}};
function switchView(view){if(view==='comparison'&&$('#result-status').textContent!=='À jour'){submit();if(!$('#errors').hidden)return;}document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==view+'-view');document.querySelectorAll('.nav').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('#view-title').textContent={calculator:'Nouvelle simulation',comparison:'Comparaison des méthodes',guide:'Méthodologie',validation:'Calibration & validation'}[view];window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>switchView(el.dataset.view));document.querySelectorAll('.return-calculator').forEach(el=>el.onclick=()=>switchView('calculator'));
$('#reset').onclick=()=>{if(!confirm('Réinitialiser les hypothèses et l’historique de cette simulation ?'))return;$('#pricing-form').reset();$('#history-body').replaceChildren();$('#parameters').open=false;switchView('calculator');dirty();submit();};
$('#export').onclick=()=>{if(!last)return;const payload={outil:'Clair — Atelier de tarification',date:new Date().toISOString(),statut:'Calibration historique ; simulation uniquement, validation commerciale non acquise',modele:model.version,empreinteModele:acceptance.artifact_sha256,baseEconomique:model.currency_basis,decisionValidation:acceptance.status,methode:names[lastInput.method],hypotheses:lastInput,resultats:last,convention:'Gamma forme/taux. Montant hors taxes, hors frais de fractionnement.'};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='clair-simulation-prime.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);};$('#print').onclick=()=>window.print();
dirty();submit();
